const response = pm.response.json();

pm.test("Status HTTP 200", function () {
pm.response.to.have.status(200);
});

pm.test("Content-Type é JSON", function () {
pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

pm.test("Tempo de resposta inferior a 300 ms", function () {
pm.expect(pm.response.responseTime).to.be.below(300);
});

pm.test("Resposta possui data, pagination e mensagens", function () {
pm.expect(response).to.have.property("data");
pm.expect(response).to.have.property("pagination");
pm.expect(response).to.have.property("mensagens");
});

pm.test("data é um array vazio", function () {
pm.expect(response.data).to.be.an("array");
pm.expect(response.data).to.have.lengthOf(0);
});

pm.test("pagination é um objeto", function () {
pm.expect(response.pagination).to.be.an("object");
pm.expect(response.pagination).to.not.be.an("array");
});

pm.test("Campos da paginação possuem tipos válidos", function () {
pm.expect(response.pagination.page).to.be.a("number");
pm.expect(response.pagination.limit).to.be.a("number");
pm.expect(response.pagination.total).to.be.a("number");
pm.expect(response.pagination.totalPages).to.be.a("number");
});

pm.test("Paginação é coerente para resposta sem registros", function () {
pm.expect(response.pagination.page).to.be.at.least(1);
pm.expect(response.pagination.limit).to.be.above(0);
pm.expect(response.pagination.total).to.eql(0);
pm.expect(response.pagination.totalPages).to.eql(0);
pm.expect(response.data.length).to.eql(0);
});

pm.test("mensagens é um array não vazio", function () {
pm.expect(response.mensagens).to.be.an("array");
pm.expect(response.mensagens.length).to.be.above(0);
});

pm.test("Mensagem informa que nenhum produto está cadastrado", function () {
const mensagemEncontrada = response.mensagens.some(function (mensagem) {
return typeof mensagem === "string" &&
/nenhum produto cadastrado/i.test(mensagem);
});

pm.expect(mensagemEncontrada).to.be.true;

});

